import { Component, EventEmitter, Output, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { IconComponent } from '@components/ui/icon/icon.component';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-add-locker-modal',
    standalone: true,
    imports: [CommonModule, FormsModule, IconComponent],
    templateUrl: './add-locker-modal.component.html',
    styleUrls: ['./add-locker-modal.component.scss']
})
export class AddLockerModalComponent implements OnInit, OnDestroy {
    @Output() close = new EventEmitter<void>();
    @Output() submit = new EventEmitter<{ address: string; name: string }>();

    address = '';
    name = '';
    error: string | null = null;

    onBackdropClick(event: MouseEvent) {
        if (event.target === event.currentTarget) {
            this.onClose();
        }
    }

    onClose() {
        this.close.emit();
    }

    onSubmit() {
        // Validate address
        if (!this.address) {
            this.error = 'Please enter an address';
            return;
        }

        if (!/^0x[a-fA-F0-9]{40}$/.test(this.address)) {
            this.error = 'Invalid Ethereum address format';
            return;
        }

        // Submit
        this.submit.emit({
            address: this.address,
            name: this.name || 'Custom Locker'
        });

        // Reset
        this.address = '';
        this.name = '';
        this.error = null;
    }

    constructor(private logger: LoggerService) {
    }

    ngOnInit(): void {
        this.logger.debug('[AddLockerModalComponent] initialized');
    }

    ngOnDestroy(): void {
        this.logger.debug('[AddLockerModalComponent] destroyed');
    }
}
